W=[
E('monitor','英 /ˈmɒnɪtə/；美 /ˈmɑːnɪtər/','监测；持续观察；显示器；监测设备；监督员','一直留意变化，必要时让人知道哪里出了问题。','借自拉丁 monitor“提醒、检查的人”，接 monere。英语动词由名词发展；显示器义沿广播、视频监测设备一系形成。',MON,'monitor progress 是持续看进展；a computer monitor 是电脑显示器；a heart monitor 是心脏监测设备。class monitor 在一些学校指班长或负责秩序的学生。它重在观察、记录，不等于直接操控。','monitor progress；monitor closely；a computer monitor；a classroom monitor。','watch 可以只是看；monitor 通常带着检查变化、记录状态的目的。display 是显示功能，monitor 还可指持续监测。',('The team will monitor the system throughout the night.','团队将整夜监测系统。'),('I connected a second monitor to my laptop.','我给笔记本电脑接了第二台显示器。'),('The class monitor handed out the worksheets.','班长分发了练习纸。'),sources=['https://www.etymonline.com/word/monitor','https://www.oxfordlearnersdictionaries.com/definition/english/monitor_1','https://www.oxfordlearnersdictionaries.com/definition/english/monitor_2']),
E('monitoring','英 /ˈmɒnɪtərɪŋ/；美 /ˈmɑːnɪtərɪŋ/','监测；持续检查','不是看一眼就走，而是在一段时间里跟踪情况怎样变。','monitor + -ing，可作动词现在分词，也常名词化表示监测过程。',MON+[['英语 monitor + -ing → monitoring','持续观察、检查这一过程']],'air quality monitoring 是空气质量监测；continuous monitoring 是连续监测。它可能发现问题，但单凭 monitoring 这个词不说明已经修复了问题。','continuous monitoring；environmental monitoring；a monitoring system。','inspection 常是一轮现场检查；monitoring 更强调持续或定期跟踪。',('Regular monitoring helps the team notice changes early.','定期监测有助于团队尽早发现变化。'),('The project includes monitoring of water quality near the factory.','这个项目包括对工厂附近水质的监测。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/monitoring','https://en.wiktionary.org/wiki/monitoring#English']),
E('monument','英 /ˈmɒnjumənt/；美 /ˈmɑːnjumənt/','纪念碑；纪念建筑；历史遗迹；体现某事的持久成果','把记忆做成一个留得住、看得见的东西。','拉丁 monumentum 来自 monere“提醒”，经法语或直接借入；英语早期也指墓葬。',MONUMENT,'a monument to someone 纪念某个人；an ancient monument 也可以是古代遗址。a monument to patience 则比喻某项成果让人看见长期耐心，不必真是一座石碑。','a monument to somebody；an ancient monument；erect a monument。','memorial 强调纪念用途，范围很广；monument 常让人想到较持久的建筑、雕塑或历史遗存。',('The town built a monument to the people who worked in the mine.','小镇建了一座纪念碑，纪念曾在矿井工作的人。'),('The restored library is a monument to years of patient work.','修复后的图书馆见证了多年耐心投入的成果。'),sources=['https://www.etymonline.com/word/monument','https://www.oxfordlearnersdictionaries.com/definition/english/monument']),
E('monumental','英 /ˌmɒnjuˈmentl/；美 /ˌmɑːnjuˈmentl/','巨大的；意义重大的；纪念碑式的','像一座大纪念碑那样显眼、分量很重，常用来放大成就、任务或错误。','借自晚期拉丁 monumentalis，接 monumentum；现代可对应 monument + -al，但并非只能看成英语内部派生。',MONUMENTAL,'a monumental achievement 是非凡成就；a monumental mistake 是大错。它并不总在赞美，也可直指纪念性建筑和雕塑。','a monumental task；a monumental achievement；a monumental mistake。','important 只说重要；monumental 常强调规模或影响大得令人难以忽视。',('Restoring the collection was a monumental task.','修复这批藏品是一项庞大的工程。'),('Deleting the only backup was a monumental mistake.','删掉唯一的备份是个大错。'),sources=['https://www.etymonline.com/word/monumental','https://www.oxfordlearnersdictionaries.com/definition/english/monumental']),
E('monumentally','英 /ˌmɒnjuˈmentəli/；美 /ˌmɑːnjuˈmentəli/','极其；非常严重地；规模巨大地','把程度推到很高，尤其常拿来形容荒唐、困难或失误有多严重。','monumental + -ly；-al 加 -ly 形成 -ally 的拼写。',MONUMENTAL+[['英语 monumental + -ly → monumentally','巨大、重大的 → 极其、非常']],'monumentally difficult 是难得惊人；monumentally stupid 是很强的负面评价。它通常作程度副词，不是在说动作像建纪念碑。','monumentally difficult；monumentally wrong；monumentally expensive。','very 语气普通；monumentally 是明显加强，适合确实想强调巨大程度的场景。',('Moving the archive turned out to be monumentally difficult.','搬迁档案最后变成了一件极其困难的事。'),('The initial forecast was monumentally wrong.','最初的预测错得离谱。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/monumentally','https://en.wiktionary.org/wiki/monumentally#English']),
E('summon','/ˈsʌmən/','召唤；传唤；鼓起、调动','发出一个有分量的呼唤，让人到场；也可以像把心里的勇气叫出来。','来自拉丁 sub- + monere → summonere，经法语 sumundre、somondre 等形式进入英语；sum- 是历史同化，不是总和 sum。',SUM,'summon someone to a meeting 是正式叫人来；summon help 是叫来援助。summon up the courage 则是努力把勇气调动起来。语气通常比随口 ask 更有紧迫性或权威性。','summon somebody to a meeting；summon help；summon up courage。','invite 给对方选择；summon 通常带有要求到场的分量，但也用于求助和文学中的召唤。',('The manager summoned the team to an urgent meeting.','经理召集团队开紧急会议。'),('She finally summoned up the courage to ask for feedback.','她终于鼓起勇气征求反馈。'),sources=['https://www.etymonline.com/word/summon','https://www.oxfordlearnersdictionaries.com/definition/english/summon']),
E('summons','/ˈsʌmənz/','传票；正式召唤；传唤〔动词〕','一份正式叫你到场的通知；词尾有 s，单数仍然可以说 a summons。','名词借自古法语 sumunse，是 somondre 分词的名词用法；不是英语 summon 的普通复数。英语后来又从这个名词派生出动词 summons。',M+[['拉丁 summonere → 古法语 somondre → sumunse','通知到场 → 正式召唤的名词'],['英语 summons〔名词〕 → summons〔动词〕','传票、召唤 → 发出正式传唤']],'a summons 是一份传票，复数 summonses。也可说 a summons to the manager’s office，指被叫去经理办公室；具体法律程序随语境，不由这个词本身规定。','receive a summons；issue a summons；a summons to appear。','summon 是常见动词；summons 既是带 s 的单数名词，也可作较专门动词。',('She received a summons to appear as a witness.','她收到了一份要求作为证人到场的传票。'),('A summons to the director’s office interrupted our discussion.','一声要我们去主管办公室的召唤打断了讨论。'),sources=['https://www.etymonline.com/word/summons','https://www.oxfordlearnersdictionaries.com/definition/english/summons_1']),
E('premonition','/ˌpriːməˈnɪʃən/','预感；不祥的预感；预先警告','事情还没发生，心里先像响了一声提醒，常觉得坏事将到。','prae- 在前 + monere 提醒形成拉丁 praemonere，接 praemonitio，再经法语进入英语；不是 pre- + 英语 monitor。',PRE+[['拉丁 praemonitio → 法语 premonicion / premunition → 英语 premonition','提前警告 → 事情发生前的预感']],'have a premonition that... 说一种先来的感觉，不等于已经有证据或真的能预知。读小说时尤其常见，现实表达也可只是强烈不安。','a premonition of danger；have a premonition that；a vague premonition。','prediction 可以基于数据作预测；premonition 更强调本人先感到某事会发生，常说不出依据。',('She had a premonition that the journey would not go as planned.','她预感这趟旅程不会按计划进行。'),('The quiet house filled him with a vague premonition of trouble.','寂静的屋子让他隐约觉得要出事。'),sources=['https://www.etymonline.com/word/premonition','https://www.oxfordlearnersdictionaries.com/definition/english/premonition']),
E('premonitory','英 /prɪˈmɒnɪtəri/；美 /prɪˈmɑːnɪtɔːri/','预兆性的；预先示警的','某个梦、迹象或感觉像在前面打了一声招呼：后面可能有事发生。','借自晚期拉丁 praemonitorius，接 praemonere 的提醒者名词 praemonitor；与 premonition 是历史旁支，不是从英语名词任意换尾。',PRE+[['拉丁 praemonitor → 晚期拉丁 praemonitorius → 英语 premonitory','提前警示的人 → 有预先警示作用的']],'a premonitory dream 是被当作预兆的梦；premonitory signs 是事前征兆。语体正式，重点是事前提醒，不要求它带神秘力量。','a premonitory dream；premonitory signs；a premonitory feeling。','ominous 强调看着不祥；premonitory 强调像是在预示后面要发生的事。',('In the novel, a premonitory dream unsettles the main character.','小说里，一个仿佛带有预兆的梦让主人公不安。'),('Only later did they recognize the noise as a premonitory sign of failure.','后来他们才意识到，那种噪声是故障出现前的征兆。'),sources=['https://www.etymonline.com/word/premonitory','https://www.oxfordlearnersdictionaries.com/definition/english/premonitory']),
E('admonition','/ˌædməˈnɪʃən/','告诫；劝诫；带提醒的责备','指出某事不妥，同时叮嘱你以后别再这样。','经法语 amonicion 接拉丁 admonitio；英语后来按拉丁词形恢复 d，不是从现代 admonish 直接截掉 -ish 再拼 -ition。',AD+[['拉丁 admonitio → 古法语 amonicion → 英语 admonition','提醒、劝告 → 对行为的告诫']],'an admonition to be careful 是叮嘱小心；stern admonition 带严肃批评。比日常 reminder 更可能含“这样做不对，下次注意”的意味。','a stern admonition；an admonition to do something；ignore an admonition。','advice 只是建议；admonition 常有劝诫、纠正行为的意味。',('He ignored her admonition to check the figures twice.','他没听她要把数字核对两遍的叮嘱。'),('The letter ended with a firm admonition against further delays.','信的结尾严正告诫，不要再继续拖延。'),sources=['https://www.etymonline.com/word/admonition','https://www.oxfordlearnersdictionaries.com/definition/english/admonition']),
E('admonitory','英 /ədˈmɒnɪtri/；美 /ədˈmɑːnɪtɔːri/','告诫的；带警告意味的','一个眼神或一句话在提醒你：注意行为，别再越线。','借自晚期拉丁 admonitorius，接 admonere 的分词词干 admonit-；不是从英语 admonition 直接派生的唯一历史。',AD+[['拉丁 admonit- → 晚期拉丁 admonitorius → 英语 admonitory','警告、劝告相关的']],'an admonitory glance 可能不用开口就让人收敛；an admonitory tone 是带劝诫意味的语气。常见于较正式或文学性的描写。','an admonitory tone；an admonitory glance；an admonitory note。','premonitory 预示将来的事；admonitory 告诫人的行为，重点是提醒改正。',('She gave the children an admonitory glance.','她向孩子们投去一个告诫的眼神。'),('The email struck an admonitory note about missed deadlines.','邮件以告诫的语气提到了逾期未完成的问题。'),sources=['https://www.etymonline.com/word/admonitory','https://www.oxfordlearnersdictionaries.com/definition/english/admonitory']),
]
U=[['拉丁语 urbs，属格 urbis','城市、城镇；更早来源未定']]
URBAN=U+[['拉丁语 urbanus → 法语或直接借入 → 英语 urban','城市的；逐渐以城市、城镇相关义为主']]
URBANE=U+[['拉丁语 urbanus → 法语 urbain 或直接借入 → 英语 urbane','城市的；沿古典引申义发展为文雅、圆熟']]
SUB=U+[['拉丁语 sub- + urbs → suburbium','城旁、近城的地方'],['古法语 suburbe → 英语 suburb','城市外围的地区，常为居住区']]
URBIZ=U+[['拉丁 urbanus 一系 → 英语 urban 与法语 urbain','城市的；旧时也含文雅义'],['英语 urban + -ize；城市化义也受法语 urbaniser 影响 → urbanize','早期有使文雅义，后常指使城市化']]
EXURBAN=URBAN+[['英语 ex- + urban → exurban','在城市之外、远郊的；形容词早于名词 exurb']]
W += [
E('urban','英 /ˈɜːbən/；美 /ˈɜːrbən/','城市的；城镇的','把视线放在城市里的人口、交通、住房和生活方式上。','来自拉丁 urbanus，接 urbs“城市”，也有经法语 urbain 的借入路线；更早来源不确定。',URBAN,'urban areas 是城镇地区，urban planning 是城市规划。urban legend 是广泛流传、真假未明的现代传说，不必发生在大城市。urban 不能自动换成某个种族名称。','urban life；urban planning；urban areas；an urban legend。','urban 说城市属性；urbane 说人文雅圆熟。住在城市里的人不一定举止 urbane。',('The study compares urban and rural transport needs.','这项研究比较了城市与乡村的交通需求。'),('The story sounds like an urban legend rather than a verified event.','这个故事听起来像都市传说，不像经过证实的事件。'),sources=['https://www.etymonline.com/word/urban','https://www.oxfordlearnersdictionaries.com/definition/english/urban']),
E('suburb','英 /ˈsʌbɜːb/；美 /ˈsʌbɜːrb/','郊区；城市外围的居住区','离市中心远一些，仍与城市生活紧密相连的区域。','拉丁 sub- 在此为靠近、在旁，接 urbs → suburbium，经古法语 suburbe 借入；不是地下城市。',SUB,'a suburb 是一个具体郊区；the suburbs 常统称城市外围住宅区。不同国家的郊区收入、密度差异很大，词本身不保证都是富人独栋住宅。','live in the suburbs；a suburb of London；a residential suburb。','outskirts 是城镇边缘地带；suburb 常是有居民生活、可辨认名称的外围社区。',('They moved to a quiet suburb with a direct train to the centre.','他们搬到一个安静的郊区，那里有直达市中心的列车。'),('Several new schools have opened in the northern suburbs.','北部郊区新开了几所学校。'),sources=['https://www.etymonline.com/word/suburb','https://www.oxfordlearnersdictionaries.com/definition/english/suburb']),
E('suburbia','英 /səˈbɜːbiə/；美 /səˈbɜːrbiə/','郊区及其生活方式','不是地图上的某一个区，而是把整个郊区世界连同生活习惯一起说出来。','英语 suburb + -ia；-ia 构成区域、集合一类名词。关于具体仿造对象有不同解释，不把它直接定成拉丁复数借入。',SUB+[['英语 suburb + -ia → suburbia','郊区整体，以及相关生活方式']],'文学和影视里 suburbia 常指通勤、住宅街、家庭生活这一整套环境。语气可能温馨，也可能在批评单调，看上下文。','life in suburbia；escape from suburbia；the routines of suburbia。','a suburb 是一处地方；suburbia 通常不可数，概括郊区环境与文化。',('The novel explores the quiet tensions beneath life in suburbia.','小说探讨了郊区生活平静表面下的紧张关系。'),('After years in the city centre, they found suburbia surprisingly peaceful.','在市中心住了多年后，他们发现郊区生活出乎意料地安宁。'),sources=['https://www.etymonline.com/word/suburbia','https://www.oxfordlearnersdictionaries.com/definition/english/suburbia']),
E('urbanism','英 /ˈɜːbənɪzəm/；美 /ˈɜːrbənɪzəm/','城市生活方式；城市规划与城市研究理念','研究人怎样在城市里生活，以及街道、住房和公共空间怎样组织这种生活。','urban + -ism；表示围绕城市的生活形态、思想或实践。',URBAN+[['英语 urban + -ism → urbanism','城市相关 → 城市生活、规划理念']],'谈 urbanism 时，关注的不只是建多少楼，还包括步行、邻里、公共空间怎样相处。它可表示城市生活特征，也可用于规划思想，具体看话题。','modern urbanism；sustainable urbanism；a study of urbanism。','urbanization 是城市化过程；urbanism 更常说城市生活的形态、研究和规划思想。',('The course explores urbanism through streets, housing and public space.','课程从街道、住房和公共空间来探讨城市生活与规划。'),('Her work connects urbanism with the everyday experience of walking.','她的研究把城市规划与日常步行体验联系起来。'),sources=['https://www.merriam-webster.com/dictionary/urbanism','https://en.wiktionary.org/wiki/urbanism#English']),
E('urbane','英 /ɜːˈbeɪn/；美 /ɜːrˈbeɪn/','文雅圆熟的；温文而善于交际的','说话有分寸、应对从容，像是很熟悉社交场合的规矩。','接拉丁 urbanus，经法语 urbain 或直接借入；与 urban 原先词形、词义相近，后来分工，不能把它当作现代 urban 加 e 才新造。',URBANE,'an urbane host 会让谈话自然、客人自在。它常带见过世面、举止圆熟的感觉，不只是穿得好，也不是所有城市居民的性格。','an urbane manner；an urbane host；urbane humour。','urban 是城市的；urbane 是人的社交风度，后者重音在后。polite 只需礼貌，不必如此圆熟。',('The host remained urbane even when the questions became awkward.','即使问题变得尴尬，主持人仍然应对得从容有礼。'),('Her urbane humour put the nervous guests at ease.','她文雅得体的幽默让紧张的客人放松下来。'),sources=['https://www.etymonline.com/word/urbane','https://www.oxfordlearnersdictionaries.com/definition/english/urbane']),
E('urbanity','英 /ɜːˈbænəti/；美 /ɜːrˈbænəti/','文雅圆熟；温文得体；城市性〔较专门义〕','把 urbane 那种从容、有礼、见过世面的风度作为一种品质来谈。','来自拉丁 urbanitas，法语也有 urbanité；英语名词有较早独立借入历史，不是只能从英语 urbane 加 -ity 解释。',U+[['拉丁 urbanus → urbanitas；法语 urbanité → 英语 urbanity','城市风格、教养 → 文雅圆熟']],'with urbanity 描写回应得得体从容。城市研究中也可用它说城市性质；一般阅读更常遇到人的举止、谈吐这一义。','great urbanity；a manner of urbanity；respond with urbanity。','urbanization 是城市化；urbanity 常是风度，不是把人搬进城的过程。',('He answered the hostile question with remarkable urbanity.','他面对带有敌意的问题，仍回答得非常从容得体。'),('The novel contrasts her public urbanity with her private anxiety.','小说对比了她在外的温文从容与私下的焦虑。'),sources=['https://www.etymonline.com/word/urbanity','https://www.oxfordlearnersdictionaries.com/definition/english/urbanity']),
E('conurbation','英 /ˌkɒnəˈbeɪʃən/；美 /ˌkɑːnərˈbeɪʃən/','连片城市区；集合城市','几座城越长越大，建成区逐渐连到一起，从地面看难分边界。','con- 一起 + 拉丁 urbs 城市 + -ation；Patrick Geddes 在二十世纪初创造的术语，不是古罗马已借出的整词。',U+[['现代英语 con- + urb- + -ation → conurbation','多个城镇连成片的城市区域']],'conurbation 强调原本独立的城镇建成区相接，不只是行政上把几个相距很远的市放在同一区域。常见于地理、交通和城市规划文字。','a large conurbation；an industrial conurbation；the edge of a conurbation。','metropolitan area 可以包括通勤圈和未连片地带；conurbation 更突出多个城镇长在一起的连续性。',('The towns expanded until they formed a single conurbation.','这些城镇不断扩张，最终连成了一片城市区。'),('Transport planning covers the whole conurbation rather than just one municipality.','交通规划覆盖整个连片城市区，而不只顾一个市。'),sources=['https://www.etymonline.com/word/conurbation','https://www.oxfordlearnersdictionaries.com/definition/english/conurbation']),
E('suburbanite','英 /səˈbɜːbənaɪt/；美 /səˈbɜːrbənaɪt/','郊区居民','把住在郊区的人作为一类来称呼，常用于生活方式或通勤话题。','suburban + -ite，-ite 在这里表示属于某地或群体的人。',U+[['拉丁 suburbanus 一系 → 英语 suburban','近郊的；现代也可对照 suburb + -an'],['英语 suburban + -ite → suburbanite','郊区的 → 郊区居民']],'可以说 a suburbanite，也可复数 suburbanites 概括郊区居民。词本身只是身份描述；具体文章可能给它加上单调、安逸等评价。','commuting suburbanites；a suburbanite’s routine；city dwellers and suburbanites。','suburban 是形容词；suburbanite 是住在那里的人，不是一个郊区地名。',('Many suburbanites use the train to reach the city centre.','许多郊区居民乘火车到市中心。'),('The survey included both city dwellers and suburbanites.','调查既包括城市中心居民，也包括郊区居民。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/suburbanite','https://en.wiktionary.org/wiki/suburbanite#English']),
E('exurb','英 /ˈeksɜːb/；美 /ˈeksɜːrb/，也有 /ɡz/ 变体','远郊居住区；郊区外围地区','比通常的郊区还往外走，但居民的工作和生活仍常与城市相连。','近源有从 exurban 反构、按 ex- 与 suburb 改造词形等解释；不能仅凭字母把它说成一个古拉丁整词。',U+[['拉丁 urbanus 一系 → 英语 urban / suburb / exurban','城市、郊区与城外的相关词'],['英语 exurb：exurban 反构说；ex- 与 suburb 改造说','城市郊区更外侧的居住地区']],'美国人口和住房报道常谈 exurbs。旧定义常强调较富裕居民，如今实际使用也可指收入不同的远郊社区；关键是位置和城市联系。','live in an exurb；growth in the exurbs；an exurb of a large city。','suburb 通常较靠近中心城市；exurb 在其更外侧，地貌可能仍带乡村特色。',('They moved to an exurb where houses were farther apart.','他们搬到一处房屋间距更大的远郊地区。'),('The new rail line connects the exurbs with the city’s business district.','新铁路把远郊居住区与城市商务区连接起来。'),sources=['https://www.etymonline.com/word/exurb','https://www.merriam-webster.com/dictionary/exurb']),
E('exurban','英 /ekˈsɜːbən/；美 /ekˈsɜːrbən/，也有 /ɡz/ 变体','远郊的；城市外围的','形容处在常规郊区外侧、又与城市保持联系的地方或生活。','ex- 在外 + urban；形容词的记录早于 exurb，不能把历史一概画成先有 exurb 再加 -an。',EXURBAN,'exurban development 是远郊开发；exurban commuters 住得更远却通勤到城里。它不等于完全与城市无关的偏远农村。','exurban communities；exurban growth；exurban commuters。','rural 泛指乡村性质；exurban 强调处在都市圈外侧的相对位置和联系。',('Exurban commuters often spend a long time travelling to work.','远郊通勤者往往花很长时间上班。'),('The report examines exurban growth along the railway.','报告研究了铁路沿线远郊地区的发展。'),sources=['https://www.etymonline.com/word/exurb','https://www.merriam-webster.com/dictionary/exurban']),
E('urbanize','英 /ˈɜːbənaɪz/；美 /ˈɜːrbənaɪz/','使城市化；使具有城市特点','原来的乡村、人口分布或生活方式逐渐变成更像城市的样子。','现代是 urban + -ize；早期还有使文雅义，城市化义也与法语 urbaniser 的影响有关。英式亦写 urbanise。',URBIZ,'urbanize an area 可说把地区发展为城市形态；become urbanized 说明人口、建筑与生活越来越城市化，不只是新盖一栋楼。','urbanize a region；rapidly urbanize；become urbanized。','industrialize 是工业化；urbanize 是城市化，两者常同时发生，却不是同一件事。',('New housing and roads helped urbanize the former farming district.','新住宅和道路促使原来的农业区逐渐城市化。'),('Much of the valley has been urbanized over the past few decades.','过去几十年里，山谷的大部分地区已经城市化。'),sources=['https://www.etymonline.com/word/urbanize','https://www.collinsdictionary.com/dictionary/english/urbanize','https://www.merriam-webster.com/dictionary/urbanize']),
E('urbanization','英 /ˌɜːbənaɪˈzeɪʃən/；美 /ˌɜːrbənəˈzeɪʃən/','城市化；城镇化','把城市人口增长、土地开发和城市生活扩展看作一个变化过程。','urbanize + -ation，构成过程名词；英式也写 urbanisation。',URBIZ+[['英语 urbanize → urbanization','使城市化 → 城市化过程']],'研究中的 urbanization 常涉及城市人口占比上升，也可谈地区的城市化改造。它不是简单地把所有房屋建高，交通、就业和基础设施也会随之变化。','rapid urbanization；the pace of urbanization；patterns of urbanization。','urbanism 常是城市生活、规划理念；urbanization 是成为更城市化社会或地区的过程。',('Rapid urbanization increased demand for housing and public transport.','快速城市化增加了住房和公共交通需求。'),('The map shows changing patterns of urbanization over a century.','地图展示了一个世纪以来城市化格局的变化。'),sources=['https://www.etymonline.com/word/urbanization','https://www.oxfordlearnersdictionaries.com/definition/english/urbanization']),
E('urbanized','英 /ˈɜːbənaɪzd/；美 /ˈɜːrbənaɪzd/','城市化了的；城市人口占比较高的','变化已经体现出来：地区建成了城市形态，或社会中多数人生活在城市。','urbanize + -ed；描述城市化后的状态，英式亦写 urbanised。',URBIZ+[['英语 urbanize + -ed → urbanized','经历城市化、具备城市特征的']],'a heavily urbanized coast 是沿海建成区密集；a highly urbanized country 常指人口高度集中在城镇。不能自动理解成每寸土地都盖了楼。','a highly urbanized society；urbanized areas；a densely urbanized coast。','urban 是城市的；urbanized 多出已经经历城市化、达到某种程度的意味。',('The eastern coast is more urbanized than the interior.','东部沿海比内陆地区更城市化。'),('Even a highly urbanized country may contain large areas of farmland.','即使城市化程度很高的国家，也可能有大片农田。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/urbanized','https://www.collinsdictionary.com/dictionary/english/urbanize']),
]
G=[['拉丁语 gravis','重的；分量大、难承受、严肃的']]
GRAVE=G+[['法语 grave → 英语 grave〔形容词〕','沉重、有分量 → 严重、严肃']]
GRAVITY=G+[['拉丁语 gravitas → 法语 gravité 或直接借入 → 英语 gravity','重量、庄重 → 严重性；重力、引力']]
GRAVARE=G+[['拉丁语 gravare → 古法语 grever','使负担加重 → 使痛苦、伤害']]
GRIEF=G+[['古法语 grief，与 grever 同族 → 英语 grief','痛苦、损害 → 悲伤、悲痛']]
GRIEVE=GRAVARE+[['英语 grieve','使悲伤；感到悲痛']]
GRIEVOUS=G+[['古法语 grevos / 盎格鲁法语 grevous → 英语 grievous','沉重难承受的 → 严重、痛苦的']]
GRAVITATE=G+[['拉丁语 gravitas → 近代拉丁 gravitare → 英语 gravitate','重量 → 受引力作用；比喻自然趋向']]
GRAVITATION=G+[['拉丁 gravitas → 近代拉丁 gravitare / gravitatio → 英语 gravitation','重量、施加重量 → 引力作用；趋向']]
AGG=G+[['拉丁语 ad- + gravare → aggravare','加上负担 → 使更严重、使痛苦']]
AGGRAVATE=AGG+[['拉丁语 aggravatus → 英语 aggravate','使负担更重 → 使恶化；使恼火']]
AGGRIEVE=AGG+[['古法语 agrever → 英语 aggrieve','使痛苦、使感到受委屈']]
W += [
E('grave','/ɡreɪv/；音乐术语另常读 /ˈɡrɑːveɪ/','严重的；严肃的；坟墓〔另源名词〕','形容词像一块沉重的石头压下来，让人知道事情不能轻看；坟墓名词另有来源。','严重义经法语 grave 接拉丁 gravis；坟墓来自古英语 græf，雕刻动词来自古英语 grafan，两条日耳曼支线不能硬接 gravis。音乐中的 grave 借自意大利语，也回到重、庄重支线。',GRAVE+[['另源：古英语 græf → 英语 grave〔坟墓〕；grafan → grave〔雕刻〕','来自挖、刻的日耳曼语支线，不接前面的拉丁形容词'],['音乐借词另线：拉丁 gravis → 意大利语 grave → 英语 grave','庄重缓慢的音乐指示；读音另行保留']],'grave danger 是严重危险；a grave expression 是严肃神情；visit a grave 是探望墓地。grave accent 是字母上的 ` 符号，名字沿低、重音调的古老说法而来，也不是坟墓上的记号。','grave concern；a grave mistake；a grave expression；visit a grave。','serious 的范围较广；grave 常显得郑重、后果重大。坟墓和严重虽然同形，不能互相推出词源。',('The report raised grave concerns about the building’s condition.','报告对建筑状况提出了严重担忧。'),('He listened with a grave expression.','他神情严肃地听着。'),('They placed flowers on their grandmother’s grave.','他们在祖母的墓前献上鲜花。'),sources=['https://www.etymonline.com/word/grave','https://www.oxfordlearnersdictionaries.com/definition/english/grave_1','https://www.oxfordlearnersdictionaries.com/definition/english/grave_2','https://www.merriam-webster.com/dictionary/grave']),
E('gravely','/ˈɡreɪvli/','严重地；严肃地；郑重地','事情的严重程度或人的神情带着沉甸甸的分量。','grave 的严重、严肃义 + -ly；不来自坟墓那个 grave。',GRAVE+[['英语 grave + -ly → gravely','严重、严肃的 → 严重地、严肃地']],'gravely ill 是病情严重；nod gravely 是郑重地点头。后者不一定带悲伤，也可能只是认真承认事情的重要性。','gravely concerned；gravely mistaken；nod gravely。','seriously 常见而宽泛；gravely 更郑重，也容易强调后果严重。',('The committee was gravely concerned about the repeated failures.','委员会对反复出现的故障深感忧虑。'),('She nodded gravely before answering the question.','她郑重地点了点头，然后回答了问题。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/gravely','https://en.wiktionary.org/wiki/gravely#English']),
E('gravity','/ˈɡrævəti/','重力；引力；严重性；庄重','一边是让物体相互吸引的物理作用，一边是事情在人心里有多大分量。','接拉丁 gravitas，经法语 gravité 或直接借入；英语早期先有重量、庄重、严重性等义，科学用法后来发展。',GRAVITY,'gravity 让苹果落地，也参与维持行星轨道，不只存在于地球。the gravity of the situation 则是形势的严重性。weight 是物体受到的重力大小或日常所说重量，不能把 gravity 当作某物的质量。','the force of gravity；Earth’s gravity；the gravity of the situation。','gravity 与 gravitation 在引力义上有重叠，gravity 更日常。gravitas 则专说人的庄重分量，不说地球引力。',('Gravity keeps the Moon in orbit around Earth.','引力使月球保持绕地球运行。'),('She did not immediately understand the gravity of the situation.','她没有立刻意识到局势有多严重。'),sources=['https://www.etymonline.com/word/gravity','https://www.oxfordlearnersdictionaries.com/definition/english/gravity','https://gracefo.jpl.nasa.gov/news/5/what-is-gravity/']),
E('gravitational','/ˌɡrævɪˈteɪʃənl/','引力的；与重力有关的','把引力这一作用贴到力、场、波等对象前面，说明讨论的是哪一种物理关系。','gravitation + -al，不是直接把 gravity 接成 gravitational。',GRAVITATION+[['英语 gravitation + -al → gravitational','引力作用 → 引力相关的']],'gravitational attraction 是引力吸引；gravitational waves 是引力波。这个形容词不会自动说明作用强弱，也不等于某物很沉重。','gravitational force；gravitational attraction；gravitational waves。','gravity 常作名词；gravitational 是完整形容词。electromagnetic 说电磁作用，是另一种相互作用。',('The two stars are held together by gravitational attraction.','这两颗恒星靠引力联系在一起。'),('The lecture explained how gravitational waves differ from sound waves.','讲座解释了引力波与声波的区别。'),sources=['https://www.etymonline.com/word/gravitation','https://www.oxfordlearnersdictionaries.com/definition/english/gravitational']),
E('gravitationally','/ˌɡrævɪˈteɪʃənəli/','通过引力；在引力作用下','说明两个天体为什么相互牵制：靠的是引力。','gravitational + -ly。',GRAVITATION+[['英语 gravitational → gravitationally','引力相关的 → 以引力方式、因引力作用']],'gravitationally bound 表示引力使一个系统保持束缚状态；gravitationally interact 是通过引力相互影响。不是“非常有分量地”的日常程度副词。','gravitationally bound；gravitationally attracted；interact gravitationally。','physically bound 范围很宽；gravitationally bound 把联系机制具体限定为引力。',('The planets are gravitationally bound to their star.','这些行星受引力束缚，围绕它们的恒星运行。'),('Nearby galaxies can interact gravitationally even when they do not collide.','相邻星系即使没有碰撞，也会通过引力相互作用。'),sources=['https://www.etymonline.com/word/gravitation','https://en.wiktionary.org/wiki/gravitationally#English']),
E('gravitation','/ˌɡrævɪˈteɪʃən/','引力作用；万有引力；趋向','把物体之间相互吸引看作一种作用或现象。','接近代拉丁 gravitare、gravitatio 一系；现代可与 gravitate + -ion 对照，但名词有独立科学借入背景。',GRAVITATION,'Newton’s law of gravitation 是牛顿万有引力定律。一般生活常用 gravity；gravitation 更容易出现在正式科学表述，也可比喻人、资源逐渐向某处集中。','universal gravitation；the law of gravitation；gravitation toward a centre。','不能把 gravitation 绝对限定为宇宙、gravity 绝对限定为地球；现代用法有明显重叠，只是习惯和具体定义可不同。',('The course introduces Newton’s law of universal gravitation.','课程介绍了牛顿万有引力定律。'),('The chapter traces the gravitation of young artists toward the capital.','这一章追溯了年轻艺术家逐渐向首都汇聚的过程。'),sources=['https://www.etymonline.com/word/gravitation','https://en.wiktionary.org/wiki/gravitation#English','https://www.oxfordlearnersdictionaries.com/definition/english/gravitation']),
E('gravitate','/ˈɡrævɪteɪt/','自然趋向；被吸引过去；受引力作用','不一定有人命令，你自己就像被吸引一样往某个人、地方或选择靠过去。','借自近代拉丁 gravitare，接 gravitas“重量”；后来常用物理吸引来比喻自然倾向。',GRAVITATE,'gravitate toward music 是自然偏爱音乐；guests gravitated to the kitchen 是客人不知不觉聚到厨房。常用不及物结构，后接 to、toward 或 towards。','gravitate towards somebody；gravitate to a place；naturally gravitate。','prefer 只说更喜欢；gravitate 常多出逐渐靠近、自然聚集的动态感觉。',('At parties, people tend to gravitate toward the kitchen.','聚会时，人们常会不知不觉聚到厨房。'),('She has always gravitated towards work that involves teaching.','她一直自然地倾向于选择与教学有关的工作。'),sources=['https://www.etymonline.com/word/gravitate','https://www.oxfordlearnersdictionaries.com/definition/english/gravitate']),
E('gravitas','/ˈɡrævɪtɑːs/，亦 /ˈɡrævɪtæs/','庄重；沉稳的分量感；令人信服的威仪','一个人不必大声讲话，别人却会觉得他说的话值得认真听。','从拉丁 gravitas 重新借入，原为重量、庄重；与 gravity 同源，但不是现代英语 gravity 的复数。',G+[['拉丁 gravitas → 英语 gravitas','重量、威严 → 人的庄重与分量感']],'a speaker with gravitas 不只是板着脸，而是举止、经验、表达让人信服。它常用于领导者、演员、公开发言者的气质，也可说作品的庄重感。','have gravitas；lend gravitas to something；a sense of gravitas。','charisma 是吸引力、感染力；gravitas 是稳重、有分量，两种气质可以共存。',('Her calm delivery gave the speech real gravitas.','她沉稳的表达让演讲很有分量。'),('The role requires an actor with warmth as well as gravitas.','这个角色需要一位既亲切又有庄重气质的演员。'),sources=['https://www.etymonline.com/word/gravitas','https://www.oxfordlearnersdictionaries.com/definition/english/gravitas']),
E('microgravity','英 /ˈmaɪkrəʊˌɡrævɪti/；美 /ˌmaɪkroʊˈɡrævɪti/','微重力；近失重环境','像人和周围东西一起自由下落，彼此之间几乎感觉不到通常的重量。','micro- 很小 + gravity；航天常用义指近失重条件，不能把字面的小误讲成空间站附近地球引力几乎消失。',GRAVITY+[['现代英语 micro- + gravity → microgravity','极小的表观重量、残余加速度所对应的近失重条件']],'空间站上的人和舱体一起绕地球自由下落，因此东西看起来漂浮。地面落塔、抛物线飞行也能短暂产生微重力环境；这里的 micro- 不是保证恰好百万分之一。','a microgravity environment；microgravity experiments；research in microgravity。','weightlessness 说失重体验；microgravity 提醒真实实验环境常仍有微小扰动。它不表示物体失去质量。',('The team studied how liquids behave in microgravity.','团队研究了液体在微重力环境中的行为。'),('A drop tower can provide a few seconds of microgravity for an experiment.','落塔可以为实验提供几秒钟的微重力环境。'),sources=['https://www.collinsdictionary.com/dictionary/english/microgravity','https://www.nasa.gov/centers-and-facilities/glenn/what-is-microgravity/','https://www.nasa.gov/centers-and-facilities/glenn/zero-gravity-research-facility/','https://www.merriam-webster.com/dictionary/microgravity']),
E('graviton','英 /ˈɡrævɪtɒn/；美 /ˈɡrævɪtɑːn/','引力子〔假设中的引力量子〕','如果用量子粒子的语言描述引力，理论上讨论的那个对应粒子叫 graviton。','现代科学造词：gravity 的词基 + 粒子名词尾 -on；不是古拉丁人已经知道的一种粒子。',GRAVITY+[['现代科学构词 gravit- + -on → graviton','引力相关的假设粒子']],'graviton 仍是理论对象，不能把引力波已被观测到等同于单个引力子已被发现。名字可以和 photon 对照记：光子是电磁场的量子，引力子是相应理论设想。','a hypothetical graviton；detect a graviton；graviton interactions。','gravitational wave 是引力波；graviton 是量子描述中的假设粒子，两个层次不同。',('The article describes the graviton as a hypothetical particle.','文章把引力子描述为一种假设粒子。'),('Detecting gravitational waves is not the same as detecting an individual graviton.','探测到引力波，不等于探测到单个引力子。'),sources=['https://home.web.cern.ch/science/physics/standard-model','https://home.web.cern.ch/science/physics/extra-dimensions-gravitons-and-tiny-black-holes/','https://en.wiktionary.org/wiki/graviton#English']),
E('grief','/ɡriːf/','悲痛；悲伤；麻烦〔口语〕','失去重要的人或事物后，心里像压着一份很重的东西。','经古法语 grief 一系接拉丁 gravis“重”；与 grever“使负担加重、使痛苦”同族，不由现代英语 grieve 机械换字母而来。',GRIEF,'grief 常说丧失带来的深切悲痛，也可用于别的严重损失。give someone grief 在口语里是给人找麻烦；Good grief! 则常是惊讶、无奈的感叹。','grief over a loss；overcome with grief；give somebody grief。','sadness 可以是短暂的一点难过；grief 通常更深，常与重要损失相关。grievance 则是不满或申诉，不是悲痛的普通替换。',('She found it difficult to speak about her grief after her brother died.','哥哥去世后，她觉得很难说出自己的悲痛。'),('The old printer has been giving us grief all morning.','那台旧打印机整个上午都在给我们添麻烦。'),sources=['https://www.etymonline.com/word/grief','https://www.oxfordlearnersdictionaries.com/definition/english/grief']),
E('grieve','/ɡriːv/','悲伤；哀悼；使悲痛','心里正在承受失去带来的痛苦，也可以说一件事让别人痛苦。','古法语 grever 来自拉丁 gravare“使沉重、使有负担”；借入英语后发展出使悲伤与感到悲伤两种常见用法。',GRIEVE,'grieve for someone 是为失去某人悲痛；grieve over a loss 是为损失难过。It grieves me to... 是正式的“……令我难过”，动作可以由人发出，也可以由事情引起。','grieve for somebody；grieve over a loss；it grieves somebody to do。','grief 是名词，grieve 是动词；词尾 /f/ 与 /v/ 也不同。mourn 更容易突出对死者的哀悼和表达。',('The family is still grieving for their father.','全家仍在为父亲的去世悲痛。'),('It grieves me to see the old building abandoned.','看到那座老建筑被遗弃，我很难过。'),sources=['https://www.etymonline.com/word/grieve','https://www.oxfordlearnersdictionaries.com/definition/english/grieve']),
E('grieving','/ˈɡriːvɪŋ/','悲痛中的；正在哀悼的','说的是一个人正处在承受失去的过程中，不是一张固定的性格标签。','grieve 去末尾 e 加 -ing；可作分词，也可作描述悲痛状态的形容词。',GRIEVE+[['英语 grieve + -ing → grieving','正在悲伤、承受丧失的过程']],'a grieving family 是正在承受丧失之痛的家庭。它不像 distressing 那样通常说“令人痛苦的”，现代常用义重点是本人感到悲痛。','a grieving parent；a grieving family；the grieving process。','grieved 常表示被某件事弄得难过；grieving 更突出仍在经历悲痛、哀悼的过程。',('Neighbours brought meals to the grieving family.','邻居们给悲痛中的一家人送来了饭菜。'),('He was still grieving and did not feel ready to return to the routine.','他仍沉浸在悲痛中，还没准备好恢复日常生活。'),sources=['https://www.etymonline.com/word/grieving','https://www.oxfordlearnersdictionaries.com/definition/english/grieving']),
E('grievous','/ˈɡriːvəs/','严重的；令人痛苦的；惨重的','事情沉重到难以承受，多形容伤害、损失和错误。','借自盎格鲁法语 grevous、古法语 grevos，接 gravis 这一族；现代可联系 grief，但形容词先在法语中形成。',GRIEVOUS,'a grievous error 是严重错误；a grievous loss 是惨重损失。它偏正式，不只是一般的不舒服。常用读音只有两个音节，不必在 /v/ 后再添一个 /i/。','a grievous error；a grievous loss；grievous harm。','grieving 是人正在悲痛；grievous 通常是事情严重、造成很大痛苦。',('The decision proved to be a grievous error.','事实证明，这个决定是一个严重错误。'),('The fire was a grievous loss to the whole community.','那场大火给整个社区带来了惨重损失。'),sources=['https://www.etymonline.com/word/grievous','https://www.oxfordlearnersdictionaries.com/definition/english/grievous']),
E('grievously','/ˈɡriːvəsli/','严重地；惨重地；令人痛苦地','把伤害、错误或辜负的程度说得很重，语体较郑重。','grievous + -ly，中古英语已有相应副词。',GRIEVOUS+[['英语 grievous + -ly → grievously','严重、难承受的 → 严重地、惨重地']],'grievously injured 是伤得严重；grievously mistaken 是大错特错。这个词不只是悲伤地说话，更常在强调某种坏结果的严重程度。','grievously injured；grievously mistaken；grievously wronged。','sadly 可以说情绪悲伤或令人遗憾；grievously 更突出损害、错误有多严重。',('Several people were grievously injured in the accident.','几个人在事故中受了重伤。'),('We were grievously mistaken about how much work remained.','我们对剩余工作量的判断大错特错。'),sources=['https://www.etymonline.com/word/grievously','https://www.oxfordlearnersdictionaries.com/definition/english/grievously']),
E('grievance','/ˈɡriːvəns/','不满；委屈；申诉事项','心里有一笔账：我被这样对待，不公平，需要有人认真处理。','借自古法语 grevance、grievance，接 grever“伤害、加负担”；不是英语 grief 随意接 -ance。',GRAVARE+[['古法语 grevance / grievance → 英语 grievance','损害、痛苦 → 对不公平待遇的不满或申诉']],'air a grievance 是把不满说出来；a grievance procedure 是组织处理员工申诉的程序。grievance 可以是主观委屈，也可以对应真实的不公，不能仅凭词语断定。','have a grievance；air grievances；a formal grievance；a grievance procedure。','complaint 可以只是抱怨服务差；grievance 更常涉及被不公平对待及正式提出的问题。',('The meeting gave staff a chance to air their grievances.','会议给了员工表达不满的机会。'),('She submitted a formal grievance about the allocation of shifts.','她就排班安排提出了正式申诉。'),sources=['https://www.etymonline.com/word/grievance','https://www.oxfordlearnersdictionaries.com/definition/english/grievance']),
E('aggrieve','/əˈɡriːv/','使受委屈；使感到不公平；使痛苦','给人的心里再压上一份不公或伤害，让他觉得受了亏待。','拉丁 ad- + gravare → aggravare，经古法语 agrever 进入英语；与 aggravate 同源，但走了不同借入路线。',AGGRIEVE,'这个动词较正式，日常更常见其形容词 aggrieved。aggrieve someone 往往不是一般逗人生气，而是让人觉得受损、受屈。','aggrieve somebody；be aggrieved by a decision；feel aggrieved。','aggravate 可使问题恶化或惹烦；aggrieve 更突出受委屈、受不公平对待的感觉。',('The unequal treatment aggrieved those who had worked the longest.','不平等的待遇让工作年限最长的人感到委屈。'),('It aggrieved her that her contribution had been ignored.','自己的贡献被忽视，让她很受委屈。'),sources=['https://www.etymonline.com/word/aggrieve','https://www.collinsdictionary.com/dictionary/english/aggrieve']),
E('aggrieved','/əˈɡriːvd/','感到受委屈的；愤愤不平的；权益受损的','心里不只是难过，还觉得这件事对自己不公平。','aggrieve + -ed；词尾读 /d/，保留动词 /v/，不是 grief 的 /f/。',AGGRIEVE+[['英语 aggrieve + -ed → aggrieved','受到伤害、不公 → 受委屈、愤愤不平']],'an aggrieved tone 听得出对不公的抱怨。法律文字里的 aggrieved party 可指权益受损一方；日常 feel aggrieved 只说明本人觉得委屈。','feel aggrieved；an aggrieved expression；an aggrieved party。','grieving 常是为丧失而悲痛；aggrieved 常是为不公而不平，感情的原因不同。',('She felt aggrieved when someone else received credit for her work.','别人因她做的工作而受表扬时，她感到很委屈。'),('He replied in an aggrieved tone that nobody had consulted him.','他愤愤不平地回答说，根本没人征求过他的意见。'),sources=['https://www.etymonline.com/word/aggrieved','https://www.oxfordlearnersdictionaries.com/definition/english/aggrieved']),
E('aggravate','/ˈæɡrəveɪt/','使恶化；加重；使恼火','原本已经有负担，再往上加一块，让情况更难受。','拉丁 ad- 同化为 ag-，加 gravare“使沉重”，经 aggravatus 借入英语；不是 ag- + 英语 grave“坟墓”。',AGGRAVATE,'aggravate a problem 是让问题更严重；aggravate someone 在口语中也可表示惹烦。这个使恼火义有长期使用历史，不必误判成新近用错。','aggravate a problem；aggravate tensions；aggravate somebody。','exacerbate 更正式，主要说恶化问题；aggravate 还能直接说某人被惹得烦。',('The delay only aggravated the shortage of supplies.','延期只让物资短缺更严重了。'),('The constant interruptions were starting to aggravate her.','不断被打断开始让她恼火。'),sources=['https://www.etymonline.com/word/aggravate','https://www.oxfordlearnersdictionaries.com/definition/english/aggravate']),
E('aggravation','/ˌæɡrəˈveɪʃən/','加重；恶化；烦恼；令人烦心的事','既可以是坏情况继续变重，也可以是人被麻烦磨出来的烦躁。','经法语 aggravation 接晚期拉丁 aggravatio；英语名词记录早于 aggravate 动词，不只画英语动词加 -ion。',AGG+[['晚期拉丁 aggravatio → 法语 aggravation → 英语 aggravation','加重负担 → 恶化；烦扰']],'the aggravation of a problem 是问题加重；save someone aggravation 是省去烦心麻烦。日常后一个意思很常见，不总是严肃的恶化。','further aggravation；avoid unnecessary aggravation；a source of aggravation。','aggravation 偏加重或惹烦；grievance 偏因不公而提出的不满，两者不能互换。',('Clear instructions would save everyone a lot of aggravation.','清楚的说明会让大家少很多烦心事。'),('The report warned of a further aggravation of the housing shortage.','报告警告，住房短缺可能进一步加剧。'),sources=['https://www.etymonline.com/word/aggravation','https://www.oxfordlearnersdictionaries.com/definition/english/aggravation']),
E('aggravating','/ˈæɡrəveɪtɪŋ/','令人恼火的；使情况更严重的','事情一直添堵、添麻烦；正式语境也可以是把问题或过错加重。','aggravate + -ing，从正在加重、惹烦的动作转成形容词。',AGGRAVATE+[['英语 aggravate + -ing → aggravating','加重、惹烦 → 令人恼火；使更严重']],'an aggravating habit 是让人烦的习惯；an aggravating factor 是使问题更严重的因素。法律文字也用后一搭配，但具体判断不是单词本身能决定的。','an aggravating habit；an aggravating factor；particularly aggravating。','annoying 主要是惹烦；aggravating 除此之外还保留加重坏情况的正式义。',('The website has an aggravating habit of logging me out.','这个网站总爱把我登出，实在烦人。'),('Poor communication was an aggravating factor in the dispute.','沟通不畅是让这场争执更加严重的一个因素。'),sources=['https://www.etymonline.com/word/aggravating','https://www.oxfordlearnersdictionaries.com/definition/english/aggravating']),
]
DEFERRED={'monitory':'低频告诫形容词，先学 admonitory。','admonitor':'罕用人物名词，暂缓。','monition':'较专门或古旧的告诫名词，优先 admonition。','resummon':'低频透明再召唤派生，暂缓。','inurbane':'罕用形容词，日常用 rude、uncouth。','inurbanity':'罕用名词，暂缓。','nonurban':'透明否定形式，先学 urban 与 rural。','gravid':'较专门的怀孕、生物描述词，暂缓。','supergravity':'较专门的理论物理术语，暂缓。','gravida':'专门产科分类术语，暂缓。','gravamen':'专门法律或学术名词，暂缓。','aggravative':'低频派生形容词，先学 aggravating。','aggravator':'低频人物或专门法律名词，暂缓。','aggrievement':'低频派生名词，先学 grievance、aggrieved。','gravidity':'专门医学、生物名词，暂缓。','grievant':'较专门劳动关系或法律称谓，暂缓。','ingravescent':'罕用医学形容词，暂缓。','multigravida':'专门产科分类术语，暂缓。','multigravidity':'专门产科名词，暂缓。','nongravitational':'专门语境透明否定形式，暂缓。','nulligravida':'专门产科分类术语，暂缓。','primigravida':'专门产科分类术语，暂缓。','reaggravate':'低频透明再加重派生，暂缓。'}
RESID_ROOT=dict(id='C1215',meaning='留下、居住；剩余与残留',core='坐下来没有马上离开：人留下是居住，东西经过变化后还留下来，就是残余。',image='re- + sedere 坐 → residere 停留；residens → resident；residentia → residence；residuus 留下的 → residuum → residue。',intro='这组是拉丁 sedere“坐、停留”的具体支线。resid- 不是英语里随便可用的新前缀，而是 residere 一系的词干形态。resident、residence、residue 各有独立借入形式；现代的相似拼写帮助联想，但不能把所有名词都画成从英语 reside 直接长出来。',forms='resident 是居民或常驻者，也可作形容词；residential 是住宅、住宿相关的。residence 常说住所或居住，residency 常说居住状态、驻留或培训安排。residue 说残留物，residual 描述残留性质。',branches=[['人留下来居住','reside, resident, nonresident'],['住所、状态与住宿安排','residence, residency, residential'],['事后留下来的东西','residue, residual']],contrasts='residence 与 residency 有重叠，但不能所有场景直接互换。resident 通常说住的人，residual 说剩下的性质。residue 的残留不一定是有害物，也可以是普通剩余部分。',practice='分别用 resident、residential、residual 描述社区居民、住宅街区和擦拭后留下的痕迹；再比较 residence 与 residency 的例句。',words=[w for w in ASSIGN['roots'][71]['family'] if w not in DEFERRED],exclude={})
MON_ROOT=dict(id='C0759',meaning='提醒、告诫；监测、纪念与召唤',core='让人注意到或想起某事：监测器不断提醒状态，纪念碑让记忆留住，召唤则把注意和人叫到眼前。',image='monere 提醒 → monitor；monumentum 让人记住的东西 → monument；prae- 提前提醒 → premonition；ad- 郑重提醒 → admonition；sub- 私下提醒 → summon。',intro='mon-、monit- 在本组接拉丁 monere。monument 不是 monitor 加词尾，monumental、premonitory、admonitory 也各有古典借词历史。summon 形状变了很多，但通过法语可以接回 summonere。',forms='monitor 名词先有监督、提醒者，动词随后发展；显示器沿监测设备支线形成。summons 的 s 属于单数词形，复数是 summonses。admonition 与 admonish 有不同法语形式，不能随意改词尾拼成。',branches=[['持续观察与提示','monitor, monitoring'],['记忆留下的东西与巨大分量','monument, monumental, monumentally'],['正式叫来与调动勇气','summon, summons'],['事先警示、预感','premonition, premonitory'],['提醒改正行为','admonish, admonition, admonishment, admonitory']],contrasts='premonition 是预感，不等于证据充分的预测；premonitory 重在事前警示，admonitory 重在劝诫行为。monitoring 负责看变化，不自动表示已经控制或修复问题。',practice='用 monitor、monument、summon 各写一句，说明提醒这个核心如何变成监测、纪念与召集；辨清 a summons 与动词 summon。',words=[w for w in ASSIGN['roots'][72]['family'] if w not in DEFERRED],exclude={w:DEFERRED[w] for w in ASSIGN['roots'][72]['family'] if w in DEFERRED})
URB_ROOT=dict(id='C1590',meaning='城市；郊区、城市化与社交风度',core='先有城市这个地方，再有城市边缘、城市连成片，以及古人联想到的城里人的教养与圆熟。',image='urbs 城 → urbanus → urban / urbane；suburbium 城旁 → suburb；urban + -ize → urbanize；con- 连在一起 + urb- → conurbation。',intro='拉丁 urbs 的更早来源不确定。urban 与 urbane 历史上词形、意义相近，后来一个主要说城市，一个主要说风度；不能把这种旧联想当作城市居民一定更有教养的事实。urbanity 有更早独立借入历史。',forms='sub- 在 suburb 中是靠近、城旁，不是地下。interurban 是城际，exurban 是城市郊区更外侧的。exurb 的近源有 exurban 反构、按 suburb 改造等说法，不画成唯一确定路径。urbanize 的城市化义也有法语 urbaniser 影响。',branches=[['城市与城市化','urban, urbanize, urbanization, urbanized, urbanism'],['城边的居住与生活','suburb, suburban, suburbia, suburbanite, exurb, exurban'],['城市间连接与连片城市','interurban, conurbation'],['温文圆熟的风度','urbane, urbanity']],contrasts='urban 是城市的，urbane 是圆熟有礼的。urbanization 是变化过程，urbanism 是城市生活或规划理念。conurbation 强调城镇建成区连片，不是任意几个城市的行政组合。',practice='比较 suburb 与 exurb，解释 interurban train 为什么不是一座城内的地铁；用 urban、urbane 各形容一个合适对象。',words=[w for w in ASSIGN['roots'][73]['family'] if w not in DEFERRED],exclude={w:DEFERRED[w] for w in ASSIGN['roots'][73]['family'] if w in DEFERRED})
GRAV_ROOT=dict(id='C0504',meaning='重、分量大；严重、悲痛与引力',core='有些重在身体上，有些重在心里：物体因引力有重量，坏消息压得人难受，严重的事情与沉稳的人也显得有分量。',image='gravis 重 → grave 严重；gravitas → gravity / gravitas；gravare 加负担 → grieve 家族；aggravare 再加重 → aggravate / aggrieve；近代科学支线 → gravitate、gravitation。',intro='主线来自拉丁 gravis，经过法语的 grief、grieve 看起来变化很大。grave 的坟墓名词与雕刻动词另来自日耳曼语，词条保留辨析但不纳入拉丁重的祖先链。gravity 与 gravitas 是同源的不同借词，后者不是前者的复数。',forms='grievance、grievous 都有法语借入背景，aggravation 也有独立的法语、拉丁名词链，不能全按现代英语动词换尾。gravitational 以 gravitation 为基底。microgravity 常说近失重环境；graviton 是假设粒子，不能与引力波混为一谈。',branches=[['严重、分量与庄重','grave, gravely, gravity, gravitas'],['引力与自然趋向','gravitate, gravitation, gravitational, gravitationally, microgravity, graviton'],['悲痛和严重伤害','grief, grieve, grieving, grievous, grievously'],['不公平带来的委屈','grievance, aggrieve, aggrieved'],['加重问题与令人烦心','aggravate, aggravation, aggravating']],contrasts='grief 是悲痛，grievance 常是不满或申诉。grieving 在承受丧失，aggrieved 觉得受了不公。aggravate 可让问题恶化，也可惹烦；gravitas 则是稳重气质。',practice='用 grief、grievance 分别描述失去亲人的感受和排班不公的抱怨；说明空间站 microgravity 为什么不等于地球引力消失。',words=[w for w in ASSIGN['roots'][74]['family'] if w not in DEFERRED],exclude={w:DEFERRED[w] for w in ASSIGN['roots'][74]['family'] if w in DEFERRED})
roots=[RESID_ROOT,MON_ROOT,URB_ROOT,GRAV_ROOT]
expected={w for r in ASSIGN['roots'][71:75] for w in r['family'] if w in set(ASSIGN['owned_words']) and w not in DEFERRED and w != 'interurban'}
assert {w['word'] for w in W}==expected,({w['word'] for w in W}-expected,expected-{w['word'] for w in W})
assert len(W)==len({w['word'] for w in W})
assert all(len(w['examples'])>=2 and all(len(e)==2 and all(e) for e in w['examples']) for w in W)
assert all(all(w.get(k) for k in ['ipa','meaning','sense','split','history','explanation','usage','contrast','sources']) for w in W)
assert all(all(len(h)==2 and all(h) for h in w['history']) for w in W)
for kind,data in [('roots',roots),('words',W)]: (OUT/f'{kind}_batch200_st_23.json').write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
